use embedded_graphics::{mock_display::MockDisplay,pixelcolor::BinaryColor,prelude::*,primitives::{Triangle,Rectangle,PrimitiveStyle}};
fn main(){ for down in [false,true] { let mut old=MockDisplay::new(); let mut new=MockDisplay::new(); let (cx,cy)=(10,10);let d=if down {-1}else{1}; Triangle::new(Point::new(cx,cy-2*d),Point::new(cx-3,cy+2*d),Point::new(cx+3,cy+2*d)).into_styled(PrimitiveStyle::with_fill(BinaryColor::On)).draw(&mut old).unwrap(); for row in 0..5i32 {let half=(row*3+if down {2}else{1})/4; Rectangle::new(Point::new(cx-half,cy+(row-2)*d),Size::new((half*2+1) as u32,1)).into_styled(PrimitiveStyle::with_fill(BinaryColor::On)).draw(&mut new).unwrap();} println!("down={down}");for y in 8..=12 {for disp in [&old,&new] {for x in 7..=13 {print!("{}",if disp.get_pixel(Point::new(x,y))==Some(BinaryColor::On){'#'}else{'.'});}print!(" ");}println!();}assert_eq!(old,new); println!("equal=true");}}
